#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;getline(cin,s);
string r;
for(char c:s){
char l=tolower((unsigned char)c);
if(l=='a'||l=='e'||l=='i'||l=='o'||l=='u')continue;
r+=c;}
printf("%s\n",r.c_str());return 0;}

